# Focus: Designing Reliable Tools
def validate_args(args):
    return set(args) == {"order_id"} and isinstance(args["order_id"], str) and args["order_id"].startswith("DEMO-")
print({"valid_demo_id": validate_args({"order_id": "DEMO-123"}), "rejects_unknown_field": not validate_args({"order_id": "DEMO-123", "export_all": True})})
